import { createRequire } from 'node:module';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const root = fileURLToPath(new URL('../../', import.meta.url)).replace(/\/$/, '');
const require = createRequire(root + '/package.json');
const { JSDOM, VirtualConsole } = require('jsdom');
const { createCanvas } = require('@napi-rs/canvas');
const html = readFileSync(root + '/dist/index.html','utf8');
const vc = new VirtualConsole(); vc.sendTo(console);
const navigationErrors = [];
vc.on('jsdomError', error => { if (/navigation/i.test(error.message)) navigationErrors.push(error.message); });
const dom = new JSDOM(html, { url:'https://jotsmedia.github.io/eternalvalley/', pretendToBeVisual:true,runScripts:'outside-only',virtualConsole:vc });
const w = dom.window;
w.localStorage.setItem('ev_user', JSON.stringify({ uid: 'saved-visitor', name: 'Returning Visitor', provider: 'guest', isGuest: true }));
for (const key of ['window','document','location','localStorage','sessionStorage','navigator','Image','HTMLElement','HTMLCanvasElement','Event','CustomEvent','Audio','getComputedStyle','MutationObserver']) Object.defineProperty(globalThis,key,{configurable:true,value:w[key]});
for (const key of ['addEventListener','removeEventListener','dispatchEvent']) globalThis[key]=w[key].bind(w);
globalThis.innerWidth=1280; globalThis.innerHeight=800; globalThis.devicePixelRatio=1;
w.matchMedia = globalThis.matchMedia = () => ({matches:false,addEventListener(){},removeEventListener(){}});
globalThis.ResizeObserver = w.ResizeObserver = class { observe() {} disconnect() {} };
globalThis.IntersectionObserver = w.IntersectionObserver = class { observe() {} unobserve() {} disconnect() {} };
globalThis.requestAnimationFrame=w.requestAnimationFrame=()=>1;
globalThis.cancelAnimationFrame=w.cancelAnimationFrame=()=>{};
globalThis.fetch=async()=>({ok:true,json:async()=>[]});
const canvases=new WeakMap();
w.HTMLCanvasElement.prototype.getContext=function(type){
  if(type!=='2d') return null;
  if(!canvases.has(this)) {
    const c=createCanvas(this.width||300,this.height||150);
    const ctx=c.getContext('2d'), draw=ctx.drawImage.bind(ctx);
    ctx.drawImage=(image,...args)=>{if(image instanceof w.HTMLImageElement)return; return draw(canvases.get(image)||image,...args);};
    canvases.set(this,c);
  }
  return canvases.get(this).getContext('2d');
};
w.HTMLMediaElement.prototype.play=async function(){this.dispatchEvent(new w.Event('play'));};
w.HTMLMediaElement.prototype.pause=function(){this.dispatchEvent(new w.Event('pause'));};
w.HTMLMediaElement.prototype.load=function(){};
let exitCode = 0;
const errors=[]; w.addEventListener('error',e=>{errors.push(e.message);console.error('DOM ERROR',e.error);});
for(const script of w.document.querySelectorAll('script:not([src])')) if(!script.type||script.type==='text/javascript') { try { w.eval(script.textContent); } catch(e){console.error('INLINE ERROR',e);} }
const entry=w.document.querySelector('script[type="module"][src]').getAttribute('src');
try {
  await import(pathToFileURL(root+'/dist/'+entry));
  assert.equal(w.UI?._initialized, true);
  assert.equal(w.__rbvBooted, true);
  await new Promise(resolve => setTimeout(resolve, 650));
  assert.equal(navigationErrors.length, 0, 'restoring a saved account must not reload the page');
  assert.equal(w.document.getElementById('userName').textContent, 'Returning Visitor');
  assert.equal(errors.length, 0);
  await w.enter('tour');
  assert.equal(w.UI._currentView, 'view2d');
  assert.equal(w.document.getElementById('veoDroneTourContainer').classList.contains('hidden'), true);
  w.document.getElementById('btn2d').click();
  await new Promise(resolve=>setTimeout(resolve,10));
  assert.equal(w.UI._currentView, 'view2d');
  w.document.getElementById('navDropdownToggle').click();
  assert.equal(w.document.getElementById('navDropdownMenu').classList.contains('hidden'), false);
  w.document.getElementById('authBtn').click();
  assert.equal(w.document.getElementById('modalRoot').classList.contains('hidden'), false);
  w.UI.closeModal();
  const banner = w.document.createElement('div');
  banner.className = 'vAygCK-api-load-alpha-banner';
  banner.getBoundingClientRect = () => ({width:1280,height:54,bottom:54});
  w.document.body.append(banner);
  await new Promise(resolve=>setTimeout(resolve,0));
  assert.equal(w.document.documentElement.style.getPropertyValue('--site-notice-height'), '54px');
  banner.remove();
  await new Promise(resolve=>setTimeout(resolve,0));
  assert.equal(w.document.documentElement.style.getPropertyValue('--site-notice-height'), '0px');
  let chosenPhase;
  w.UI.world = {forcePhase(value) { chosenPhase = value; },stop() {}};
  w.document.querySelector('.sap-btn[data-phase="dawn"]').click();
  assert.equal(chosenPhase, 'dawn');
  w.UI.world = null;
  w.document.getElementById('btn3d').click();
  await new Promise(resolve=>setTimeout(resolve,10));
  assert.equal(w.UI._currentView, 'view2d');
  assert.equal(errors.length, 0);
  console.log('Built startup, navigation, notice clearance, lighting, and WebGL fallback passed.');
} catch(e){ console.error('STARTUP CHECK FAILED',e); exitCode = 1; }
finally { w.UI?.map?.destroy(); w.close();process.exit(exitCode); }
